<script lang="ts">
import {Component} from 'vue-property-decorator'
import PortalPageBase from '@/view/PortalPageBase'
import {breadcrumbList, canonicalUrl, pageMetaInfo, personStub, socialCardPath} from '@/model/Seo'
import {brandName} from '@/model/Brand'
import SitePageHeader from '@/view/SitePageHeader.vue'

@Component({components: {SitePageHeader}})
export default class Contact extends PortalPageBase {
  pageTitle = this.titles.contactPage

  metaInfo(): any {
    const structuredData = {
      '@context': 'https://schema.org',
      '@graph': [
        {
          '@type': 'ContactPage',
          name: this.titles.contactPage,
          description: this.titles.contactDescription,
          url: canonicalUrl(this.constants.contactPath),
          mainEntity: personStub(this.model.profile)
        },
        breadcrumbList([
          {name: brandName, path: '/'},
          {name: this.titles.homePage, path: this.constants.introductionPath},
          {name: this.titles.contactPage, path: this.constants.contactPath}
        ])
      ]
    }
    return pageMetaInfo(
      this.titles.contactSeoTitle,
      this.titles.contactDescription,
      this.constants.contactPath,
      socialCardPath(this.constants.contactPath),
      structuredData
    )
  }

  beforeRouteEnter(to: any, from: any, next: any) {
    super.beforeRouteEnter(to, from, next)
  }
}
</script>
